head.script:
scwin.onpageload = function() {
    var totRow = 200;
    var totCol = grid1.getTotalCol();
    var arr = [];
    for (var i = 0; i < totRow; i++) {
        for (var j = 0; j < totCol; j++) {
            if (j != 0) {
                arr.push("index_" + i + "_" + j);
            } else {
                arr.push("");
            }
        }
    }
    grid1.setData(arr);
    grid1.setCellChecked(0, "chk", true);
    grid1.setCellChecked(4, "chk", true);
    grid1.setCellChecked(5, "chk", true);
    grid1.setCellChecked(6, "chk", true);
    grid1.setCellChecked(7, "chk", true);
    grid1.setCellChecked(9, "chk", true);
    grid1.setCellChecked(10, "chk", true);
    grid1.setCellChecked(12, "chk", true);
    grid1.setCellChecked(13, "chk", true);
};
scwin.onpageunload = function() {};
scwin.select11_onviewchange = function(info) {
    var value = info.value;
    grid1.clearRowVisible();
    if (value == "1") {
        //				grid1.clearRowVisible();
    } else if (value == "2") {
        for (var i = 0; i < grid1.getTotalRow(); i++) {
            var chk = grid1.getCellChecked(i, 0);
            if (!chk) {
                grid1.setRowVisible(i, false);
            }
        }
    } else if (value == "3") {
        for (var i = 0; i < grid1.getTotalRow(); i++) {
            var chk = grid1.getCellChecked(i, 0);
            if (chk) {
                grid1.setRowVisible(i, false);
            }
        }
    }
};
scwin.compareValue = function(id1, id2) {
    if (WebSquare.wUnit.getDomById($p.id + id1).textContent == WebSquare.wUnit.getDomById($p.id + id2).textContent) {
        return false;
    }
    return true;
}
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 상단의 radio버튼을 순서대로 전체 > 선택 > 미선택 > 선택 > 전체 를 클릭한다.
    //1. After running the sample, click the radio button at the top and select All> Select> Unselect> Select> All.
    //Verify step 1. Duplicate columns are not visible.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('#select11_input_0').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('#select11_input_1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('#select11_input_2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('#select11_input_1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('#select11_input_0').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.compareValue($p.id+'grid1_cell_3_1', 'grid1_cell_4_1')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.compareValue($p.id+'grid1_cell_8_1', 'grid1_cell_9_1')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.compareValue($p.id+'grid1_cell_11_1', 'grid1_cell_12_1')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 22-Feb-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
